+  readonly id: string;
+  readonly text: string;
+  readonly x: number;
+  readonly y: number;
+}
+
+export interface ControlTowerVisual {
+  readonly viewBox: string;
+  readonly zones: readonly VisualZone[];
+  readonly aisles: readonly VisualAisle[];
+  readonly binCells: readonly VisualBinCell[];
+  readonly labels: readonly VisualTextLabel[];
+  readonly legend: readonly { status: BinStatus; label: string }[];
+}
+
+export interface VisualCapability {
+  readonly svgElements: number;
+  readonly heatmapCells: number;
+  readonly textLabels: number;
+}
+
+const DEFAULT_BIN_CAPACITY = 40;
+const ZONE_WIDTH = 214;
+const ZONE_HEIGHT = 168;
+const BIN_WIDTH = 84;
+const BIN_HEIGHT = 46;
+const ZONE_GAP = 28;
+const ORIGIN_X = 28;
+const ORIGIN_Y = 42;
+
+function binCapacity(bin: Bin): number {
+  return bin.capacity ?? DEFAULT_BIN_CAPACITY;
+}
+
+export function binStatus(occupancy: number): BinStatus {
+  if (occupancy === 0) return "empty";
+  if (occupancy >= 0.9) return "critical";
+  if (occupancy >= 0.7) return "watch";
+  return "healthy";
+}
+
+export function buildControlTowerVisual(scenario: Scenario): ControlTowerVisual {
+  const zones: VisualZone[] = scenario.layout.zones.map((zone, index) => ({
+    id: zone.id,
+    name: zone.name,
+    x: ORIGIN_X + index * (ZONE_WIDTH + ZONE_GAP),
+    y: ORIGIN_Y,
+    width: ZONE_WIDTH,
+    height: ZONE_HEIGHT,
+  }));
+
+  const zoneById = new Map(zones.map((zone) => [zone.id, zone]));
+  const binCounters = new Map<string, number>();
+  const binCells = scenario.layout.bins.map((bin) => {
+    const zone = zoneById.get(bin.zoneId);
+    if (zone === undefined) {
+      throw new Error(`bin ${bin.id} references unknown visual zone: ${bin.zoneId}`);
+    }
+
+    const slot = binCounters.get(bin.zoneId) ?? 0;
+    binCounters.set(bin.zoneId, slot + 1);
+
+    const quantity = totalUnitsForBin(scenario.inventory, bin.id);
+    const capacity = binCapacity(bin);
+    const occupancy = Math.min(quantity / capacity, 1);
+    const status = binStatus(occupancy);
+    const row = Math.floor(slot / 2);
+    const column = slot % 2;
+
+    return {
+      binId: bin.id,
+      code: bin.code,
+      zoneId: bin.zoneId,
+      x: zone.x + 18 + column * (BIN_WIDTH + 16),
+      y: zone.y + 46 + row * (BIN_HEIGHT + 14),
+      width: BIN_WIDTH,
+      height: BIN_HEIGHT,
+      quantity,
+      capacity,
+      occupancy,
+      status,
+      label: `${bin.code} ${quantity}/${capacity}`,
+    };
+  });
+
+  const labels: VisualTextLabel[] = [
+    ...zones.map((zone) => ({
+      id: `zone-label-${zone.id}`,
+      text: zone.name,
+      x: zone.x + 16,
+      y: zone.y + 25,
+    })),
+    ...binCells.map((cell) => ({
+      id: `bin-label-${cell.binId}`,
+      text: cell.label,
+      x: cell.x + 8,
+      y: cell.y + 28,
+    })),
+    { id: "legend-label", text: "Stock heatmap: qty/capacity and status", x: ORIGIN_X, y: 256 },
+  ];
+
+  const aisles: VisualAisle[] = zones.slice(0, -1).map((zone, index) => ({
+    id: `aisle-${index + 1}`,
+    label: `Aisle ${index + 1}`,
+    x1: zone.x + zone.width + ZONE_GAP / 2,
+    y1: ORIGIN_Y + 20,
+    x2: zone.x + zone.width + ZONE_GAP / 2,
+    y2: ORIGIN_Y + ZONE_HEIGHT - 20,
+  }));
+
+  return {
+    viewBox: "0 0 996 300",
+    zones,
+    aisles,
+    binCells,
+    labels,
+    legend: [
+      { status: "critical", label: "Critical >= 90%" },
+      { status: "watch", label: "Watch >= 70%" },
+      { status: "healthy", label: "Healthy < 70%" },
+      { status: "empty", label: "Empty 0%" },
+    ],
+  };
+}
+
+export function visualCapability(visual: ControlTowerVisual): VisualCapability {
+  return {
+    svgElements:
+      visual.zones.length +
+      visual.aisles.length +
+      visual.binCells.length +
+      visual.labels.length +
+      visual.legend.length * 2,
+    heatmapCells: visual.binCells.length,
+    textLabels: visual.labels.length + visual.legend.length,
+  };
+}

